package com.example.gr01_1bt3_622_26a.config;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;

import java.util.*;

/**
 *  Interceptor de Autenticación y Autorización
 *
 * Responsabilidades:
 * - Verificar sesión activa antes de acceder a rutas protegidas
 * - Validar roles de usuario para rutas específicas
 * - Redirigir a login si no hay sesión
 * - Redirigir a acceso denegado si no tiene permisos
 *
 * Rutas Protegidas:
 * - /admin/** → Requiere rol ADMIN
 * - /solicitudes/** → Requiere autenticació (SOLICITANTE)
 * - /solicitantes/** (excepto registro) → Requiere autenticación
 * - /adopciones/** → Puede requerir autenticación según contexto
 */
@Component
@Slf4j
public class AuthInterceptor implements HandlerInterceptor {

    // Rutas que NO requieren autenticación
    private static final Set<String> RUTAS_PUBLICAS = new HashSet<>(Arrays.asList(
            "/",
            "/login",
            "/login/admin",
            "/login/procesar",
            "/login/admin/procesar",
            "/logout",
            "/acceso",
            "/solicitantes/registro",
            "/solicitantes/registrar",
            "/usuarios/registro",
            "/usuarios/crear",
            "/mascotas",
            "/mascotas/disponibles",
            "/mascotas/buscar"
    ));

    // Rutas que requieren rol ADMIN
    private static final Set<String> RUTAS_ADMIN = new HashSet<>(Arrays.asList(
            "/admin"
    ));

    // Rutas que requieren autenticación (cualquier rol)
    private static final Set<String> RUTAS_AUTENTICADAS = new HashSet<>(Arrays.asList(
            "/solicitudes",
            "/adopciones"
    ));

    @Override
    public boolean preHandle(HttpServletRequest request,
                             HttpServletResponse response,
                             Object handler) throws Exception {

        String requestURI = request.getRequestURI();

        log.debug(" [AUTH] Verificando acceso a: {}", requestURI);

        // Verificar si es ruta pública
        if (esRutaPublica(requestURI)) {
            log.debug("✓ Ruta pública permitida: {}", requestURI);
            return true;
        }

        // Obtener sesión
        HttpSession session = request.getSession(false);

        // Verificar sesión activa
        if (session == null || session.getAttribute("usuarioId") == null) {
            log.warn("⚠️ [AUTH] Intento de acceso sin sesión a: {}", requestURI);

            // Redirigir según tipo de ruta
            if (requestURI.startsWith("/admin")) {
                response.sendRedirect("/login/admin");
            } else {
                response.sendRedirect("/login");
            }
            return false;
        }

        String rol = (String) session.getAttribute("rol");
        String email = (String) session.getAttribute("email");

        // Verificar rol si es ruta admin
        if (esRutaAdmin(requestURI)) {
            if (!"ADMIN".equals(rol)) {
                log.warn("⚠️ [AUTH] Usuario {} intentó acceso admin sin permisos", email);
                response.sendRedirect("/acceso");
                return false;
            }

            log.info("✅ [AUTH] Acceso admin permitido para: {}", email);
            return true;
        }

        // Verificar si es ruta autenticada
        if (esRutaAutenticada(requestURI)) {
            log.info("✅ [AUTH] Acceso autenticado permitido para {} (rol: {})", email, rol);
            return true;
        }

        // Acceso permitido (otras rutas)
        return true;
    }

    /**
     * Verificar si una ruta es pública (sin necesidad de autenticación)
     */
    private boolean esRutaPublica(String uri) {
        return RUTAS_PUBLICAS.stream()
                .anyMatch(uri::startsWith);
    }

    /**
     * Verificar si una ruta requiere rol ADMIN
     */
    private boolean esRutaAdmin(String uri) {
        return RUTAS_ADMIN.stream()
                .anyMatch(uri::startsWith);
    }

    /**
     * Verificar si una ruta requiere autenticación
     */
    private boolean esRutaAutenticada(String uri) {
        return RUTAS_AUTENTICADAS.stream()
                .anyMatch(uri::startsWith);
    }

    /**
     *  REFACTOR: Validar si un ID de usuario es válido
     *
     * Lógica PURA sin dependencias externas
     * - ID nulo → false
     * - ID <= 0 → false
     * - ID > 0 → true
     *
     * @param usuarioId ID del usuario
     * @return true si ID es válido (> 0), false en caso contrario
     */
    public boolean isValidUsuarioId(Long usuarioId) {
        return usuarioId != null && usuarioId > 0;
    }

    /**
     *  REFACTOR: Validar si un rol es ADMIN
     *
     * Lógica PURA sin dependencias externas
     * - Compara string de rol con constante "ADMIN"
     * - Null-safe
     *
     * @param rol Rol a validar
     * @return true si rol es "ADMIN", false en caso contrario
     */
    public boolean isRolAdmin(String rol) {
        return rol != null && "ADMIN".equals(rol);
    }

    @Override
    public void afterCompletion(HttpServletRequest request,
                                HttpServletResponse response,
                                Object handler,
                                Exception ex) throws Exception {

        if (ex != null) {
            log.error("❌ [AUTH] Error durante procesamiento de request: {}", request.getRequestURI(), ex);
        }
    }
}

package com.example.gr01_1bt3_622_26a.config;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;

import java.util.*;

/**
 *  Interceptor de Autenticación y Autorización
 *
 * Responsabilidades:
 * - Verificar sesión activa antes de acceder a rutas protegidas
 * - Validar roles de usuario para rutas específicas
 * - Redirigir a login si no hay sesión
 * - Redirigir a acceso denegado si no tiene permisos
 *
 * Rutas Protegidas:
 * - /admin/** → Requiere rol ADMIN
 * - /solicitudes/** → Requiere autenticació (SOLICITANTE)
 * - /solicitantes/** (excepto registro) → Requiere autenticación
 * - /adopciones/** → Puede requerir autenticación según contexto
 */
@Component
@Slf4j
public class AuthInterceptor implements HandlerInterceptor {

    // Rutas que NO requieren autenticación
    private static final Set<String> RUTAS_PUBLICAS = new HashSet<>(Arrays.asList(
            "/",
            "/login",
            "/login/admin",
            "/login/procesar",
            "/login/admin/procesar",
            "/logout",
            "/acceso",
            "/solicitantes/registro",
            "/solicitantes/registrar",
            "/usuarios/registro",
            "/usuarios/crear",
            "/mascotas",
            "/mascotas/disponibles",
            "/mascotas/buscar"
    ));

    // Rutas que requieren rol ADMIN
    private static final Set<String> RUTAS_ADMIN = new HashSet<>(Arrays.asList(
            "/admin"
    ));

    // Rutas que requieren autenticación (cualquier rol)
    private static final Set<String> RUTAS_AUTENTICADAS = new HashSet<>(Arrays.asList(
            "/solicitudes",
            "/adopciones"
    ));

    @Override
    public boolean preHandle(HttpServletRequest request,
                             HttpServletResponse response,
                             Object handler) throws Exception {

        String requestURI = request.getRequestURI();

        log.debug(" [AUTH] Verificando acceso a: {}", requestURI);

        // Verificar si es ruta pública
        if (esRutaPublica(requestURI)) {
            log.debug("✓ Ruta pública permitida: {}", requestURI);
            return true;
        }

        // Obtener sesión
        HttpSession session = request.getSession(false);

        // Verificar sesión activa
        if (session == null || session.getAttribute("usuarioId") == null) {
            log.warn("⚠️ [AUTH] Intento de acceso sin sesión a: {}", requestURI);

            // Redirigir según tipo de ruta
            if (requestURI.startsWith("/admin")) {
                response.sendRedirect("/login/admin");
            } else {
                response.sendRedirect("/login");
            }
            return false;
        }

        String rol = (String) session.getAttribute("rol");
        String email = (String) session.getAttribute("email");

        // Verificar rol si es ruta admin
        if (esRutaAdmin(requestURI)) {
            if (!"ADMIN".equals(rol)) {
                log.warn("⚠️ [AUTH] Usuario {} intentó acceso admin sin permisos", email);
                response.sendRedirect("/acceso");
                return false;
            }

            log.info("✅ [AUTH] Acceso admin permitido para: {}", email);
            return true;
        }

        // Verificar si es ruta autenticada
        if (esRutaAutenticada(requestURI)) {
            log.info("✅ [AUTH] Acceso autenticado permitido para {} (rol: {})", email, rol);
            return true;
        }

        // Acceso permitido (otras rutas)
        return true;
    }

    /**
     * Verificar si una ruta es pública (sin necesidad de autenticación)
     */
    private boolean esRutaPublica(String uri) {
        return RUTAS_PUBLICAS.stream()
                .anyMatch(uri::startsWith);
    }

    /**
     * Verificar si una ruta requiere rol ADMIN
     */
    private boolean esRutaAdmin(String uri) {
        return RUTAS_ADMIN.stream()
                .anyMatch(uri::startsWith);
    }

    /**
     * Verificar si una ruta requiere autenticación
     */
    private boolean esRutaAutenticada(String uri) {
        return RUTAS_AUTENTICADAS.stream()
                .anyMatch(uri::startsWith);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // CONSTANTES PARA VALIDACIONES
    // ─────────────────────────────────────────────────────────────────────────
    private static final Long ID_MINIMO_VALIDO = 0L;
    private static final String ROL_ADMIN = "ADMIN";

    /**
     *  REFACTOR: Validar si un ID de usuario es válido
     *
     * Lógica PURA sin dependencias externas
     * - Mejoras en esta fase:
     *   ✓ Constante para ID_MINIMO_VALIDO
     *   ✓ Documentación clara del comportamiento
     *   ✓ Legibilidad mejorada
     *
     * Criterios de validez:
     * - ID != null
     * - ID > 0 (mayor que ID_MINIMO_VALIDO)
     *
     * @param usuarioId ID del usuario a validar
     * @return true si ID es válido (> 0 y no null), false en caso contrario
     */
    public boolean isValidUsuarioId(Long usuarioId) {
        if (usuarioId == null) {
            return false;
        }
        return usuarioId > ID_MINIMO_VALIDO;
    }

    /**
     *  REFACTOR: Validar si un rol es ADMIN
     *
     * Lógica PURA sin dependencias externas
     * - Mejoras en esta fase:
     *   ✓ Constante para ROL_ADMIN
     *   ✓ Validación null-safe mejorada
     *   ✓ Documentación clara
     *
     * Solo acepta exactamente "ADMIN" (case-sensitive)
     *
     * @param rol Rol a validar (case-sensitive)
     * @return true si rol es exactamente "ADMIN", false en caso contrario
     */
    public boolean isRolAdmin(String rol) {
        if (rol == null) {
            return false;
        }
        return ROL_ADMIN.equals(rol);
    }

    @Override
    public void afterCompletion(HttpServletRequest request,
                                HttpServletResponse response,
                                Object handler,
                                Exception ex) throws Exception {

        if (ex != null) {
            log.error("❌ [AUTH] Error durante procesamiento de request: {}", request.getRequestURI(), ex);
        }
    }
}

package com.example.gr01_1bt3_622_26a.controller;

import com.example.gr01_1bt3_622_26a.entity.Usuario;
import com.example.gr01_1bt3_622_26a.service.UsuarioService;
import jakarta.servlet.http.HttpSession;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

/**
 *  Controlador de Autenticación y Manejo de Sesiones
 *
 * Responsabilidades:
 * - Mostrar formularios de login (solicitante y admin)
 * - Procesar credenciales de entrada
 * - Crear sesiones del usuario
 * - Cerrar sesiones (logout)
 * - Redirigir según rol
 *
 * Ciclo TDD:
 *  RED: No existe LoginController
 *  GREEN: Se crea controlador mínimo
 *  REFACTOR: Se mejora con validaciones, logging y manejo de sesiones
 */
@Controller
@RequiredArgsConstructor
@Slf4j
public class LoginController {

    private final UsuarioService usuarioService;

    // ========== FORMULARIOS DE LOGIN ==========

    /**
     * Mostrar formulario de login para solicitantes
     */
    @GetMapping("/login")
    public String mostrarLoginSolicitante(HttpSession session) {
        log.info(" Accediendo a formulario de login de solicitante");

        // Si ya hay sesión activa, redirigir al dashboard
        if (session.getAttribute("usuarioId") != null) {
            String rol = (String) session.getAttribute("rol");
            log.info("✓ Usuario ya autenticado con rol: {}", rol);
            return rol != null && rol.equals("ADMIN")
                    ? "redirect:/admin/dashboard"
                    : "redirect:/solicitudes/mis-solicitudes";
        }

        return "login/loginSolicitante";
    }

    /**
     * Mostrar formulario de login para administradores
     */
    @GetMapping("/login/admin")
    public String mostrarLoginAdmin(HttpSession session) {
        log.info(" Accediendo a formulario de login de administrador");

        // Si hay sesión admin, redirigir al dashboard
        if (session.getAttribute("usuarioId") != null) {
            String rol = (String) session.getAttribute("rol");
            if ("ADMIN".equals(rol)) {
                log.info("✓ Admin ya autenticado");
                return "redirect:/admin/dashboard";
            }
        }

        return "login/loginAdmin";
    }

    /**
     * Mostrar formulario de acceso público
     */
    @GetMapping("/acceso")
    public String mostrarAcceso() {
        log.info(" Accediendo a página de selección de acceso");
        return "login/acceso";
    }

    // ========== PROCESAMIENTO DE LOGIN ==========

    /**
     * Procesar login de solicitante
     *
     * @param email Email del solicitante
     * @param password Contraseña
     * @param session Sesión HTTP para almacenar datos de usuario
     * @param model Modelo para pasar datos a la vista
     * @param redirectAttributes Atributos para redireccionamiento con mensaje flash
     * @return Redirección a dashboard o vuelta al login con error
     */
    @PostMapping("/login/procesar")
    public String procesarLoginSolicitante(
            @RequestParam String email,
            @RequestParam String password,
            HttpSession session,
            Model model,
            RedirectAttributes redirectAttributes) {

        log.info(" [LOGIN] Intento de autenticación de solicitante: {}", email);

        try {
            // Validar credenciales
            Usuario usuario = usuarioService.iniciarSesion(email, password);

            // Verificar rol
            if (!usuario.getRol().equals(Usuario.RolUsuario.SOLICITANTE)) {
                log.warn("⚠️ [LOGIN] Usuario con rol incorrecto intentando acceso solicitante: {}", email);
                redirectAttributes.addFlashAttribute("error",
                        "Este usuario no tiene permiso para acceso de solicitante. Use el login de administrador.");
                return "redirect:/acceso";
            }

            // Crear sesión
            crearSesion(session, usuario);

            log.info("✅ [LOGIN] Sesión iniciada para solicitante: {} (ID: {})", email, usuario.getId());
            return "redirect:/solicitudes/mis-solicitudes";

        } catch (IllegalArgumentException e) {
            log.warn("⚠️ [LOGIN] Error de autenticación para {}: {}", email, e.getMessage());
            redirectAttributes.addFlashAttribute("error", "Email o contraseña incorrectos");
            return "redirect:/login";
        } catch (Exception e) {
            log.error("❌ [LOGIN] Error inesperado durante login: {}", e.getMessage(), e);
            redirectAttributes.addFlashAttribute("error", "Error al procesar login. Intente nuevamente.");
            return "redirect:/login";
        }
    }

    /**
     * Procesar login de administrador
     *
     * @param email Email del administrador
     * @param password Contraseña
     * @param session Sesión HTTP
     * @param redirectAttributes Atributos para mensajes flash
     * @return Redirección a dashboard admin o error
     */
    @PostMapping("/login/admin/procesar")
    public String procesarLoginAdmin(
            @RequestParam String email,
            @RequestParam String password,
            HttpSession session,
            RedirectAttributes redirectAttributes) {

        log.info(" [LOGIN] Intento de autenticación de administrador: {}", email);

        try {
            // Validar credenciales
            Usuario usuario = usuarioService.iniciarSesion(email, password);

            // Verificar rol
            if (!usuario.getRol().equals(Usuario.RolUsuario.ADMIN)) {
                log.warn("⚠️ [LOGIN] Usuario con rol incorrecto intentando acceso admin: {}", email);
                redirectAttributes.addFlashAttribute("error",
                        "Este usuario no tiene permisos de administrador. Use el login de solicitante.");
                return "redirect:/acceso";
            }

            // Crear sesión
            crearSesion(session, usuario);

            log.info("✅ [LOGIN] Sesión iniciada para admin: {} (ID: {})", email, usuario.getId());
            return "redirect:/admin/dashboard";

        } catch (IllegalArgumentException e) {
            log.warn("⚠️ [LOGIN] Error de autenticación para admin {}: {}", email, e.getMessage());
            redirectAttributes.addFlashAttribute("error", "Email o contraseña incorrectos");
            return "redirect:/login/admin";
        } catch (Exception e) {
            log.error("❌ [LOGIN] Error inesperado durante login admin: {}", e.getMessage(), e);
            redirectAttributes.addFlashAttribute("error", "Error al procesar login. Intente nuevamente.");
            return "redirect:/login/admin";
        }
    }

    // ========== LOGOUT ==========

    /**
     * Cerrar sesión del usuario
     *
     * @param session Sesión HTTP a invalidar
     * @param redirectAttributes Atributos para mensajes flash
     * @return Redirección a página de inicio
     */
    @GetMapping("/logout")
    public String logout(HttpSession session, RedirectAttributes redirectAttributes) {
        Long usuarioId = (Long) session.getAttribute("usuarioId");

        if (usuarioId != null) {
            try {
                // Invocar servicio de logout en BD
                usuarioService.cerrarSesion(usuarioId);
                log.info("✅ [LOGOUT] Sesión cerrada para usuario ID: {}", usuarioId);
            } catch (Exception e) {
                log.warn("⚠️ [LOGOUT] Error al cerrar sesión en BD para ID {}: {}", usuarioId, e.getMessage());
            }
        }

        // Invalidar sesión HTTP
        session.invalidate();
        log.info("✅ [LOGOUT] Sesión HTTP invalidada");

        redirectAttributes.addFlashAttribute("mensaje", "¡Has cerrado sesión exitosamente!");
        return "redirect:/acceso";
    }

    // ========== MÉTODOS AUXILIARES ==========

    /**
     * Crear sesión HTTP después de autenticación exitosa
     *
     * @param session Sesión HTTP
     * @param usuario Usuario autenticado
     */
    private void crearSesion(HttpSession session, Usuario usuario) {
        // Configurar tiempo de expiración (30 minutos)
        session.setMaxInactiveInterval(30 * 60);

        // Almacenar datos en sesión
        session.setAttribute("usuarioId", usuario.getId());
        session.setAttribute("email", usuario.getEmail());
        session.setAttribute("nombre", usuario.getNombre());
        session.setAttribute("rol", usuario.getRol().toString());
        session.setAttribute("documentoIdentidad", usuario.getDocumentoIdentidad());

        log.debug("✓ Sesión creada para usuario {} con ID: {}", usuario.getEmail(), usuario.getId());
    }
}

package com.example.gr01_1bt3_622_26a.controller;

import com.example.gr01_1bt3_622_26a.entity.Usuario;
import com.example.gr01_1bt3_622_26a.service.UsuarioService;
import jakarta.servlet.http.HttpSession;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

/**
 *  Controlador de Autenticación y Manejo de Sesiones
 *
 * Responsabilidades:
 * - Mostrar formularios de login (solicitante y admin)
 * - Procesar credenciales de entrada
 * - Crear sesiones del usuario
 * - Cerrar sesiones (logout)
 * - Redirigir según rol
 *
 * Ciclo TDD:
 *  RED: No existe LoginController
 *  GREEN: Se crea controlador mínimo
 *  REFACTOR: Se mejora con validaciones, logging y manejo de sesiones
 */
@Controller
@RequiredArgsConstructor
@Slf4j
public class LoginController {

    private final UsuarioService usuarioService;

    // ========== FORMULARIOS DE LOGIN ==========

    /**
     * Mostrar formulario de login para solicitantes
     */
    @GetMapping("/login")
    public String mostrarLoginSolicitante(HttpSession session) {
        log.info(" Accediendo a formulario de login de solicitante");

        // Si ya hay sesión activa, redirigir al dashboard
        if (session.getAttribute("usuarioId") != null) {
            String rol = (String) session.getAttribute("rol");
            log.info("✓ Usuario ya autenticado con rol: {}", rol);
            return rol != null && rol.equals("ADMIN")
                    ? "redirect:/admin/dashboard"
                    : "redirect:/solicitudes/mis-solicitudes";
        }

        return "login/loginSolicitante";
    }

    /**
     * Mostrar formulario de login para administradores
     */
    @GetMapping("/login/admin")
    public String mostrarLoginAdmin(HttpSession session) {
        log.info(" Accediendo a formulario de login de administrador");

        // Si hay sesión admin, redirigir al dashboard
        if (session.getAttribute("usuarioId") != null) {
            String rol = (String) session.getAttribute("rol");
            if ("ADMIN".equals(rol)) {
                log.info("✓ Admin ya autenticado");
                return "redirect:/admin/dashboard";
            }
        }

        return "login/loginAdmin";
    }

    /**
     * Mostrar formulario de acceso público
     */
    @GetMapping("/acceso")
    public String mostrarAcceso() {
        log.info(" Accediendo a página de selección de acceso");
        return "login/acceso";
    }

    // ========== PROCESAMIENTO DE LOGIN ==========

    /**
     * Procesar login de solicitante
     *
     * @param email Email del solicitante
     * @param password Contraseña
     * @param session Sesión HTTP para almacenar datos de usuario
     * @param model Modelo para pasar datos a la vista
     * @param redirectAttributes Atributos para redireccionamiento con mensaje flash
     * @return Redirección a dashboard o vuelta al login con error
     */
    @PostMapping("/login/procesar")
    public String procesarLoginSolicitante(
            @RequestParam String email,
            @RequestParam String password,
            HttpSession session,
            Model model,
            RedirectAttributes redirectAttributes) {

        log.info(" [LOGIN] Intento de autenticación de solicitante: {}", email);

        try {
            // Validar credenciales
            Usuario usuario = usuarioService.iniciarSesion(email, password);

            // Verificar rol
            if (!usuario.getRol().equals(Usuario.RolUsuario.SOLICITANTE)) {
                log.warn("⚠️ [LOGIN] Usuario con rol incorrecto intentando acceso solicitante: {}", email);
                redirectAttributes.addFlashAttribute("error",
                        "Este usuario no tiene permiso para acceso de solicitante. Use el login de administrador.");
                return "redirect:/acceso";
            }

            // Crear sesión
            crearSesion(session, usuario);

            log.info("✅ [LOGIN] Sesión iniciada para solicitante: {} (ID: {})", email, usuario.getId());
            return "redirect:/solicitudes/mis-solicitudes";

        } catch (IllegalArgumentException e) {
            log.warn("⚠️ [LOGIN] Error de autenticación para {}: {}", email, e.getMessage());
            redirectAttributes.addFlashAttribute("error", "Email o contraseña incorrectos");
            return "redirect:/login";
        } catch (Exception e) {
            log.error("❌ [LOGIN] Error inesperado durante login: {}", e.getMessage(), e);
            redirectAttributes.addFlashAttribute("error", "Error al procesar login. Intente nuevamente.");
            return "redirect:/login";
        }
    }

    /**
     * Procesar login de administrador
     *
     * @param email Email del administrador
     * @param password Contraseña
     * @param session Sesión HTTP
     * @param redirectAttributes Atributos para mensajes flash
     * @return Redirección a dashboard admin o error
     */
    @PostMapping("/login/admin/procesar")
    public String procesarLoginAdmin(
            @RequestParam String email,
            @RequestParam String password,
            HttpSession session,
            RedirectAttributes redirectAttributes) {

        log.info(" [LOGIN] Intento de autenticación de administrador: {}", email);

        try {
            // Validar credenciales
            Usuario usuario = usuarioService.iniciarSesion(email, password);

            // Verificar rol
            if (!usuario.getRol().equals(Usuario.RolUsuario.ADMIN)) {
                log.warn("⚠️ [LOGIN] Usuario con rol incorrecto intentando acceso admin: {}", email);
                redirectAttributes.addFlashAttribute("error",
                        "Este usuario no tiene permisos de administrador. Use el login de solicitante.");
                return "redirect:/acceso";
            }

            // Crear sesión
            crearSesion(session, usuario);

            log.info("✅ [LOGIN] Sesión iniciada para admin: {} (ID: {})", email, usuario.getId());
            return "redirect:/admin/dashboard";

        } catch (IllegalArgumentException e) {
            log.warn("⚠️ [LOGIN] Error de autenticación para admin {}: {}", email, e.getMessage());
            redirectAttributes.addFlashAttribute("error", "Email o contraseña incorrectos");
            return "redirect:/login/admin";
        } catch (Exception e) {
            log.error("❌ [LOGIN] Error inesperado durante login admin: {}", e.getMessage(), e);
            redirectAttributes.addFlashAttribute("error", "Error al procesar login. Intente nuevamente.");
            return "redirect:/login/admin";
        }
    }

    // ========== LOGOUT ==========

    /**
     * Cerrar sesión del usuario
     *
     * @param session Sesión HTTP a invalidar
     * @param redirectAttributes Atributos para mensajes flash
     * @return Redirección a página de inicio
     */
    @GetMapping("/logout")
    public String logout(HttpSession session, RedirectAttributes redirectAttributes) {
        Long usuarioId = (Long) session.getAttribute("usuarioId");

        if (usuarioId != null) {
            try {
                // Invocar servicio de logout en BD
                usuarioService.cerrarSesion(usuarioId);
                log.info("✅ [LOGOUT] Sesión cerrada para usuario ID: {}", usuarioId);
            } catch (Exception e) {
                log.warn("⚠️ [LOGOUT] Error al cerrar sesión en BD para ID {}: {}", usuarioId, e.getMessage());
            }
        }

        // Invalidar sesión HTTP
        session.invalidate();
        log.info("✅ [LOGOUT] Sesión HTTP invalidada");

        redirectAttributes.addFlashAttribute("mensaje", "¡Has cerrado sesión exitosamente!");
        return "redirect:/acceso";
    }

    // ========== MÉTODOS AUXILIARES ==========

    /**
     * Crear sesión HTTP después de autenticación exitosa
     *
     * @param session Sesión HTTP
     * @param usuario Usuario autenticado
     */
    public void crearSesion(HttpSession session, Usuario usuario) {
        // Configurar tiempo de expiración (30 minutos)
        session.setMaxInactiveInterval(30 * 60);

        // Almacenar datos en sesión
        session.setAttribute("usuarioId", usuario.getId());
        session.setAttribute("email", usuario.getEmail());
        session.setAttribute("nombre", usuario.getNombre());
        session.setAttribute("rol", usuario.getRol().toString());
        session.setAttribute("documentoIdentidad", usuario.getDocumentoIdentidad());

        log.debug("✓ Sesión creada para usuario {} con ID: {}", usuario.getEmail(), usuario.getId());
    }

    /**
     * Validar que el usuario tenga rol ADMIN
     *
     * @param usuario Usuario a validar
     * @throws IllegalArgumentException si el usuario no es ADMIN
     */
    public void validarRolAdmin(Usuario usuario) {
        if (!usuario.getRol().equals(Usuario.RolUsuario.ADMIN)) {
            log.warn("⚠️ Intento de acceso admin por usuario sin permisos: {}", usuario.getEmail());
            throw new IllegalArgumentException("Usuario no tiene permisos de administrador");
        }
        log.debug("✓ Usuario validado como ADMIN: {}", usuario.getEmail());
    }
}

package com.example.gr01_1bt3_622_26a.entity;

import jakarta.persistence.*;
import jakarta.validation.constraints.*;
import lombok.*;
import java.time.LocalDate;
import java.util.List;

/**
 * Entidad que representa una mascota disponible para adopción
 */
@Entity
@Table(name = "mascotas")
@Data
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Mascota {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @NotBlank(message = "El nombre de la mascota es requerido")
    @Size(min = 2, max = 100, message = "El nombre debe tener entre 2 y 100 caracteres")
    @Column(nullable = false)
    private String nombre;

    @NotBlank(message = "El tipo de mascota es requerido")
    @Column(nullable = false)
    private String tipo; // Perro, Gato, Conejo, etc.

    @Size(max = 50, message = "La raza no debe exceder 50 caracteres")
    private String raza;

    @NotNull(message = "La edad es requerida")
    @Min(value = 0, message = "La edad no puede ser negativa")
    @Max(value = 50, message = "La edad no puede exceder 50 años")
    private Integer edad;

    @NotBlank(message = "El género es requerido")
    @Column(nullable = false)
    private String genero; // Macho, Hembra

    @Size(max = 500, message = "La descripción no debe exceder 500 caracteres")
    @Column(length = 500)
    private String descripcion;

    @Column(name = "fecha_registro")
    private LocalDate fechaRegistro;

    @NotBlank(message = "El estado es requerido")
    @Column(nullable = false)
    private String estado; // Disponible, Adoptado, En proceso, etc.

    @Size(max = 255, message = "El color no debe exceder 255 caracteres")
    private String color;

    @Column(name = "peso_kg")
    private Double pesoKg;

    // Relación con fotos
    @OneToMany(mappedBy = "mascota", cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.LAZY)
    private List<Foto> fotos;

    @PrePersist
    protected void onCreate() {
        if (fechaRegistro == null) {
            fechaRegistro = LocalDate.now();
        }
        if (estado == null) {
            estado = "Disponible";
        }
    }
}

